        c.init(vader, usdv, vault);

        vm.prank(address(0x100));
        c.newAddressProposal(address(0x1234), "DAO");

        vm.prank(address(0x101));
        c.newAddressProposal(address(0x5678), "DAO");





        vm.prank(address(0x100));
        c.newAddressProposal(address(0x1234), "DAO");
        address addrAfterCreation = c.mapPID_address(1);

        assertTrue(addrAfterCreation != address(0), "mapPID_address should not be zero");
